//     Unread: status === MARK_AS_STATUS.UNREAD ? 1 : 0,
// });

export const applyMarkAsChangesOnConversation = (
    conversation: Conversation,
    labelID: string,
    { status }: MarkAsChanges
) => {
    const { NumUnread = 0, Labels = [] } = conversation;
    const { ContextNumUnread = 0 } = Labels.find(({ ID }) => ID === labelID) || {};
    const updatedNumUnread =
        status === MARK_AS_STATUS.UNREAD ? NumUnread + 1 : Math.max(NumUnread - ContextNumUnread, 0);
    const updatedContextNumUnread = status === MARK_AS_STATUS.UNREAD ? ContextNumUnread + 1 : 0;
    const updatedLabels = Labels.map((label) =>
        label.ID === labelID
            ? {
                  ...label,
                  ContextNumUnread: updatedContextNumUnread,
              }
            : label
    );

    return {
        ...conversation,
        NumUnread: updatedNumUnread,
        ContextNumUnread: updatedContextNumUnread,
        Labels: updatedLabels,
    };
};

// Here only one message is marked as read/unread
const applyMarkAsChangesOnConversationWithMessages = (
    conversation: Conversation,
    labelID: string,
    { status }: MarkAsChanges
) => {
    const { NumUnread = 0, Labels = [] } = conversation;
    const { ContextNumUnread = 0 } = Labels.find(({ ID }) => ID === labelID) || {};
    const updatedNumUnread = status === MARK_AS_STATUS.UNREAD ? NumUnread + 1 : Math.max(NumUnread - 1, 0);
    const updatedContextNumUnread =
        status === MARK_AS_STATUS.UNREAD ? ContextNumUnread + 1 : Math.max(ContextNumUnread - 1, 0);
    const updatedLabels = Labels.map((label) =>
        label.ID === labelID
            ? {
                  ...label,
                  ContextNumUnread: updatedContextNumUnread,
              }
            : label
    );

    return {
        ...conversation,
        NumUnread: updatedNumUnread,
        ContextNumUnread: updatedContextNumUnread,
        Labels: updatedLabels,
    };
};

export const useOptimisticMarkAs = () => {
    const dispatch = useAppDispatch();
    const getElementByID = useGetElementByID();
    const globalCache = useCache();
    const [mailSettings] = useMailSettings();
    const history = useHistory();
    const getConversation = useGetConversation();

    const optimisticMarkAs = useHandler((elements: Element[], labelID: string, changes: MarkAsChanges) => {
        const rollbackChanges = [] as { element: Element; changes: MarkAsChanges }[];
        const updatedElements = [] as Element[];
        let { value: messageCounters } = globalCache.get(MessageCountsModel.key) as CacheEntry<LabelCount[]>;
        let { value: conversationCounters } = globalCache.get(ConversationCountsModel.key) as CacheEntry<LabelCount[]>;

        elements.forEach((element) => {
            rollbackChanges.push({ element, changes: computeRollbackMarkAsChanges(element, labelID, changes) });

            if (testIsMessage(element)) {
                const message = element as Message;

                dispatch(optimisticMarkAsMessageAction({ ID: message.ID, changes }));

                // Update in conversation cache
                const conversationState = getConversation(message.ConversationID);
                if (conversationState && conversationState.Conversation) {
                    const conversation = conversationState.Conversation;
                    const updatedConversation = applyMarkAsChangesOnConversationWithMessages(
                        conversation,
                        labelID,
                        changes
                    );

                    dispatch(
                        optimisticMarkAsConversationMessages({
                            ID: message.ConversationID,
                            messageID: message.ID,
                            updatedConversation,
                            changes,
                        })
                    );

                    // Update conversation count when the conversation is loaded
                    conversationCounters = updateCountersForMarkAs(
                        conversation,
                        updatedConversation,
                        conversationCounters
                    );
                }

                // Updates in elements cache if message mode
                const messageElement = getElementByID(message.ID);
                if (messageElement && messageElement.ID) {
                    const updatedMessage = applyMarkAsChangesOnMessage(messageElement as Message, changes);
                    updatedElements.push(updatedMessage);

                    // Update counters
                    messageCounters = updateCountersForMarkAs(message, updatedMessage, messageCounters);
                }

                // Update in elements cache if conversation mode
                const conversationElement = getElementByID(message.ConversationID);
                if (conversationElement && conversationElement.ID) {
                    updatedElements.push(
                        applyMarkAsChangesOnConversationWithMessages(conversationElement, labelID, changes)
                    );
                }
            } else {
                // isConversation
                const conversation = element as RequireSome<Conversation, 'ID'>;

                // Update in conversation cache
                dispatch(optimisticMarkAsConversation({ ID: conversation.ID, labelID, changes }));

                // Update in elements cache if conversation mode
                const conversationElement = getElementByID(conversation.ID);
                if (conversationElement && conversationElement.ID) {
                    const updatedConversation = applyMarkAsChangesOnConversation(conversationElement, labelID, changes);
                    updatedElements.push(updatedConversation);

                    // Update counters
                    conversationCounters = updateCountersForMarkAs(
                        conversationElement,
                        updatedConversation,
                        conversationCounters
                    );
                }

                // Update messages from the conversation (if loaded)
                if (changes.status === MARK_AS_STATUS.READ) {
                    const messages = getConversation(conversation.ID)?.Messages;
                    messages?.forEach((message) => {
                        if (!message.LabelIDs.find((id) => id === labelID)) {
                            return;
                        }

                        dispatch(optimisticMarkAsMessageAction({ ID: message.ID, changes }));
                    });
                }
            }
        });

        if (updatedElements.length) {
            // When changing the read / unread status of an element
            // We want them to stay on the current filter even if it doesn't match the filter anymore
            // So we manually update the elements cache to mark these ids to bypass the filter logic
            // This will last as long as the cache is not reset (cf useElements shouldResetCache)
            const conversationMode = isConversationMode(labelID, mailSettings, history.location);
            dispatch(optimisticMarkAsElementAction({ elements: updatedElements, bypass: true, conversationMode }));
        }

        globalCache.set(MessageCountsModel.key, { value: messageCounters, status: STATUS.RESOLVED });
        globalCache.set(ConversationCountsModel.key, { value: conversationCounters, status: STATUS.RESOLVED });

        return () => {
            rollbackChanges.forEach(({ element, changes }) => optimisticMarkAs([element], labelID, changes));
        };
    });

    return optimisticMarkAs;
};
import { PayloadAction } from '@reduxjs/toolkit';
import { Draft } from 'immer';

import { toMap } from '@proton/shared/lib/helpers/object';
import { Message } from '@proton/shared/lib/interfaces/mail/Message';
import diff from '@proton/utils/diff';
import isTruthy from '@proton/utils/isTruthy';
import range from '@proton/utils/range';

import { MAX_ELEMENT_LIST_LOAD_RETRIES, PAGE_SIZE } from '../../constants';
import { parseLabelIDsInEvent, isMessage as testIsMessage } from '../../helpers/elements';
import { Element } from '../../models/element';
import { newState } from './elementsSlice';
import {
    ESResults,
    ElementsState,
    EventUpdates,
    NewStateParams,
    OptimisticDelete,
    OptimisticUpdates,
    QueryParams,
    QueryResults,
    TaskRunningInfo,
} from './elementsTypes';
import { newRetry } from './helpers/elementQuery';

export const globalReset = (state: Draft<ElementsState>) => {
    Object.assign(state, newState());
};

export const reset = (state: Draft<ElementsState>, action: PayloadAction<NewStateParams>) => {
    Object.assign(
        state,
        newState({
            ...action.payload,
            taskRunning: { labelIDs: state.taskRunning.labelIDs, timeoutID: state.taskRunning.timeoutID },
        })
    );
};

export const updatePage = (state: Draft<ElementsState>, action: PayloadAction<number>) => {
    state.page = action.payload;
};

export const retry = (
    state: Draft<ElementsState>,
    action: PayloadAction<{ queryParameters: any; error: Error | undefined }>
) => {
    state.beforeFirstLoad = false;
    state.invalidated = false;
    state.pendingRequest = false;
    state.retry = newRetry(state.retry, action.payload.queryParameters, action.payload.error);
};

const hasSameMode = (state: Draft<ElementsState>, arg: QueryParams) => {
    return state.params.conversationMode === arg.params.conversationMode;
};

export const loadPending = (
    state: Draft<ElementsState>,
    action: PayloadAction<undefined, string, { arg: QueryParams }>
) => {
    if (hasSameMode(state, action.meta.arg)) {
        state.pendingRequest = true;
        state.page = action.meta.arg.page;
    }
};

export const loadFulfilled = (
    state: Draft<ElementsState>,
    action: PayloadAction<{ result: QueryResults; taskRunning: TaskRunningInfo }, string, { arg: QueryParams }>
) => {
    const { page, params } = action.meta.arg;
    const {
        result: { Total, Elements },
        taskRunning,
    } = action.payload;
    if (hasSameMode(state, action.meta.arg)) {
        Object.assign(state, {
            beforeFirstLoad: false,
            invalidated: false,
            pendingRequest: false,
            page,
            total: Total,
            retry: newRetry(state.retry, params, undefined),
        });
        state.pages.push(page);
        Object.assign(state.elements, toMap(Elements, 'ID'));
        state.taskRunning = taskRunning;
    }
};

export const manualPending = (state: Draft<ElementsState>) => {
    state.pendingRequest = true;
};

export const manualFulfilled = (state: Draft<ElementsState>) => {
    state.pendingRequest = false;
};

export const removeExpired = (state: Draft<ElementsState>, action: PayloadAction<Element>) => {
    delete state.elements[action.payload.ID || ''];
};

export const invalidate = (state: Draft<ElementsState>) => {
    state.invalidated = true;
};

export const eventUpdatesPending = (
    state: Draft<ElementsState>,
    action: PayloadAction<undefined, string, { arg: EventUpdates }>
) => {
    const { toCreate, toUpdate, toDelete } = action.meta.arg;
    toCreate.forEach((element) => {
        state.elements[element.ID || ''] = element;
    });
    toUpdate.forEach((element) => {
        const existingElement = state.elements[element.ID || ''];
        if (existingElement) {
            state.elements[element.ID || ''] = parseLabelIDsInEvent(existingElement, element);
        }
    });
    toDelete.forEach((elementID) => {
        delete state.elements[elementID];
    });
};

export const eventUpdatesFulfilled = (
    state: Draft<ElementsState>,
    action: PayloadAction<(Element | undefined)[], string, { arg: EventUpdates }>
) => {
    action.payload.filter(isTruthy).forEach((element) => {
        state.elements[element.ID || ''] = element;
    });
};

export const addESResults = (state: Draft<ElementsState>, action: PayloadAction<ESResults>) => {
    const total = action.payload.elements.length;
    const pages = range(0, Math.ceil(total / PAGE_SIZE));
    // Retry is disabled for encrypted search results, to avoid re-triggering the search several times
    // when there are no results
    Object.assign(state, {
        bypassFilter: [],
        beforeFirstLoad: false,
        invalidated: false,
        pendingRequest: false,
        page: action.payload.page,
        total,
        pages,
        elements: toMap(action.payload.elements, 'ID'),
        retry: { payload: undefined, count: MAX_ELEMENT_LIST_LOAD_RETRIES, error: undefined },
    });
};

export const optimisticUpdates = (state: Draft<ElementsState>, action: PayloadAction<OptimisticUpdates>) => {
    action.payload.elements.forEach((element) => {
        if (element.ID) {
            state.elements[element.ID] = element;
        }
    });
    if (action.payload.isMove) {
        const elementIDs = action.payload.elements.map(({ ID }) => ID || '');
        state.bypassFilter = diff(state.bypassFilter, elementIDs);
    }
    if (action.payload.bypass) {
        const { conversationMode } = action.payload;
        action.payload.elements.forEach((element) => {
            const isMessage = testIsMessage(element);
            const id = (isMessage && conversationMode ? (element as Message).ConversationID : element.ID) || '';
            if (!state.bypassFilter.includes(id)) {
                state.bypassFilter.push(id);
            }
        });
    }
};

export const optimisticDelete = (state: Draft<ElementsState>, action: PayloadAction<OptimisticDelete>) => {
    action.payload.elementIDs.forEach((elementID) => {
        delete state.elements[elementID];
    });
};

export const optimisticEmptyLabel = (state: Draft<ElementsState>) => {
    state.elements = {};
    state.page = 0;
};

export const backendActionStarted = (state: Draft<ElementsState>) => {
    state.pendingActions++;
};

export const backendActionFinished = (state: Draft<ElementsState>) => {
    state.pendingActions--;
};

export const moveAllFulfilled = (
    state: Draft<ElementsState>,
    { payload: { LabelID, timeoutID } }: PayloadAction<{ LabelID: string; timeoutID: NodeJS.Timeout }>
) => {
    if (!state.taskRunning.labelIDs.includes(LabelID)) {
        state.taskRunning.labelIDs.push(LabelID);
    }
    state.taskRunning.timeoutID = timeoutID;
};

export const pollTaskRunningFulfilled = (state: Draft<ElementsState>, { payload }: PayloadAction<TaskRunningInfo>) => {
    state.taskRunning = payload;
};

export const deleteDraft = (state: Draft<ElementsState>, { payload: ID }: PayloadAction<string>) => {
    delete state.elements[ID];
};

import { Api } from '@proton/shared/lib/interfaces';

import { Element } from '../../models/element';
import { LabelIDsChanges } from '../../models/event';
import { Filter, SearchParameters, Sort } from '../../models/tools';

export interface ElementsStateParams {
    labelID: string;
    conversationMode: boolean;
    sort: Sort;
    filter: Filter;
    search: SearchParameters;
    esEnabled: boolean;
}

export interface RetryData {
    payload: any;
    count: number;
    error: Error | undefined;
}

export interface TaskRunningInfo {
    labelIDs: string[];
    timeoutID: NodeJS.Timeout | undefined;
}

export interface ElementsState {
    /**
     * True when the first request has not been sent
     * Allow to show a loading state even before the first request is sent
     */
    beforeFirstLoad: boolean;

    /**
     * The cache is invalidated and the request should be re-sent
     */
    invalidated: boolean;

    /**
     * A request is currently pending
     */
    pendingRequest: boolean;

    /**
     * An action is pending backend side on the element list and it shouldnt be refreshed yet
     */
    pendingActions: number;

    /**
     * Current parameters of the list (label, filter, sort, search)
     */
    params: ElementsStateParams;

    /**
     * Current page number
     */
    page: number;

    /**
     * List of page number currently in the cache
     */
    pages: number[];

    /**
     * Total of elements returned by the current request
     * Undefined before the request return
     * Warning, if the user perform move actions, this value can be hugely outdated
     */
    total: number | undefined;

    /**
     * Actual cache of elements indexed by there ids
     * Contains all elements loaded since last cache reset
     */
    elements: { [ID: string]: Element };

    /**
     * List of element's id which are allowed to bypass the current filter
     */
    bypassFilter: string[];

    /**
     * Retry data about the last request
     * Keeps track of the last request to count the number of attemps
     */
    retry: RetryData;

    /**
     * Labels on which on task is currently running
     */
    taskRunning: TaskRunningInfo;
}

export interface QueryParams {
    api: Api;
    call: () => Promise<void>;
    abortController: AbortController | undefined;
    conversationMode: boolean;
    page: number;
    params: ElementsStateParams;
    count?: number;
}

export interface QueryResults {
    abortController: AbortController;
    Total: number;
    Elements: Element[];
    Stale: number;
    /**
     * About TasksRunning:
     * - Returns an empty array when no results
     * - Returns a object when results
     * - TasksRunning key does not exist when LabelID is not present in query params.
     */
    TasksRunning?: { [labelID: string]: any } | string[];
}

export interface NewStateParams {
    page?: number;
    params?: Partial<ElementsStateParams>;
    retry?: RetryData;
    beforeFirstLoad?: boolean;
}

export interface EventUpdates {
    api: Api;
    conversationMode: boolean;
    toCreate: (Element & LabelIDsChanges)[];
    toUpdate: (Element & LabelIDsChanges)[];
    toLoad: string[];
    toDelete: string[];
}

export interface ESResults {
    page: number;
    elements: Element[];
}

export interface OptimisticUpdates {
    elements: Element[];
    isMove?: boolean;
    bypass?: boolean;
    conversationMode?: boolean;
}

export interface OptimisticDelete {
    elementIDs: string[];
}
